@extends('layouts.app') @section('title',$x->number) @section('content')<a href="{{route('requests.index')}}">← Обращения</a><div class="d-flex justify-content-between"><h1 class="h4">{{$x->number}} · {{$x->title}}</h1><span class="badge text-bg-secondary">{{$x->status}}</span></div><div class="card card-body mb-3"><small>{{$x->department}} / {{$x->category_name}} · приоритет {{$x->priority}} · срок {{$x->due_at}} · исполнитель {{$x->assignee_name?:'не назначен'}}</small><div class="mt-2">{!! nl2br(e($x->description)) !!}</div>@if($x->resolution)<hr><b>Решение</b><div>{{$x->resolution}}</div>@endif</div>@if($files->count())<div class="mb-3"><b>📎 Вложения:</b> @foreach($files as $f)<a class="me-2" href="{{route('requests.file',$f->id)}}">{{$f->original_name}}</a>@endforeach</div>@endif@if(auth()->user()->isSuperAdmin()||auth()->user()->hasRole('request_dispatcher')||auth()->user()->canDo('requests.manage'))<form method="post" action="{{route('requests.update',$x->id)}}" class="card card-body row g-2 mb-3">@csrf<div class="col-md-2"><select name="status" class="form-select">@foreach(['new','assigned','in_progress','waiting','resolved','closed','cancelled'] as $s)<option @selected($x->status===$s)>{{$s}}</option>@endforeach</select></div><div class="col-md-3"><select name="assigned_to" class="form-select"><option value="">Исполнитель</option>@foreach($users as $u)<option value="{{$u->id}}" @selected($x->assigned_to==$u->id)>{{$u->name}}</option>@endforeach</select></div><div class="col-md-2"><select name="priority" class="form-select">@foreach(['low','normal','high','urgent'] as $p)<option @selected($x->priority===$p)>{{$p}}</option>@endforeach</select></div><div class="col-md-4"><input name="resolution" value="{{$x->resolution}}" class="form-control" placeholder="Решение"></div><div class="col"><button class="btn btn-primary">Сохранить</button></div></form>@endif<h2 class="h6">💬 Переписка</h2>@foreach($messages as $m)<div class="card card-body mb-2 {{$m->internal?'border-warning':''}}"><b>{{$m->user_name}} <small>{{$m->created_at}}</small></b><div>{!! nl2br(e($m->message)) !!}</div>@if($m->internal)<small>Внутренняя заметка</small>@endif</div>@endforeach<form method="post" action="{{route('requests.message',$x->id)}}" class="card card-body mb-3">@csrf<textarea name="message" class="form-control mb-2" required placeholder="Ответить"></textarea>@if(auth()->user()->isSuperAdmin()||auth()->user()->hasRole('request_dispatcher')||auth()->user()->canDo('requests.manage'))<label><input type="checkbox" name="internal" value="1"> внутренняя заметка (заявитель её не увидит)</label>@endif<button class="btn btn-outline-primary mt-2">Отправить</button></form>@if($x->official_appeal)<form method="post" action="{{route('requests.edo',$x->id)}}" class="mb-3">@csrf<button class="btn btn-outline-dark">📑 Передать обращение в ЭДО</button></form>@endif@if(in_array($x->status,['resolved','closed'])&&$x->created_by===auth()->id())<form method="post" action="{{route('requests.rate',$x->id)}}" class="card card-body">@csrf<b>Оцените решение</b><div class="d-flex gap-2"><select name="rating" class="form-select w-auto">@for($i=5;$i>=1;$i--)<option value="{{$i}}">{{$i}} / 5</option>@endfor</select><input name="rating_comment" class="form-control" placeholder="Комментарий"><button class="btn btn-success">Оценить</button></div></form>@endif @endsection